                                v[6 * GL_NL + l] = g * x000_300_0;
                                v[7 * GL_NL + l] = g * x000_210_0;
                                v[8 * GL_NL + l] = g * x000_201_0;
                                v[9 * GL_NL + l] = g * x000_120_0;
                                v[10 * GL_NL + l] = g * x000_111_0;
