                        o[2 * s0 + 0 * s1 + 4 * s2 + 3 * s3 + l] = fac * (0.596831036594607678 * R[8 * GL_NL + l] + -0.596831036594607678 * R[62 * GL_NL + l]);
                        o[0 * s0 + 0 * s1 + 4 * s2 + 4 * s3 + l] = fac * (0.298415518297303839 * R[0 * GL_NL + l] + -0.298415518297303839 * R[9 * GL_NL + l] + -0.298415518297303839 * R[54 * GL_NL + l] + 0.298415518297303839 * R[63 * GL_NL + l]);
                        o[1 * s0 + 0 * s1 + 4 * s2 + 4 * s3 + l] = fac * (0.298415518297303839 * R[1 * GL_NL + l] + -0.298415518297303839 * R[10 * GL_NL + l] + -0.298415518297303839 * R[55 * GL_NL + l] + 0.298415518297303839 * R[64 * GL_NL + l]);
                        o[2 * s0 + 0 * s1 + 4 * s2 + 4 * s3 + l] = fac * (0.298415518297303839 * R[2 * GL_NL + l] + -0.298415518297303839 * R[11 * GL_NL + l] + -0.298415518297303839 * R[56 * GL_NL + l] + 0.298415518297303839 * R[65 * GL_NL + l]);
