/* (11|00) on GL_NL lanes: 15 VRR nodes, 9 targets */
static int jkl_1100(double *out, const size_t *st, const int *pos, const GPair *B, int bs,
                const LaneK *K, double cut, double fac, const double *tab, double *wk)
{
        const int nb = B->n, nk = K->nk, ncb = B->nc, nck = K->nck;
        const double *pax = bs ? B->rjx : B->rix, *pay = bs ? B->rjy : B->riy, *paz = bs ? B->rjz : B->riz;
        double *v = wk, *SK = v + (size_t)9 * GL_NL;
        int t, b, cb, kc, i, l, any = 0;
        memset(SK, 0, sizeof(double) * nck * ncb * 9 * GL_NL);
        for (t = 0; t < nk; t++) {
                if (K->bmx[t] < cut) continue;
                any = 1;
                const int nbt = n_above(B->beta, nb, cut * B->bmax / K->bmx[t]);
                const double q = K->q[t], h2q = .5 / q;
                const double *QX = K->qx[t], *QY = K->qy[t], *QZ = K->qz[t], *KP = K->kp[t];
                const double *QCX = K->qcx[t], *QCY = K->qcy[t], *QCZ = K->qcz[t];
                (void)h2q; (void)QCX; (void)QCY; (void)QCZ;
                for (b = 0; b < nbt; b++) {
                        const double p = B->p[b], s = 1. / (p + q), rho = p * q * s;
                        const double h2p = .5 / p, rp = rho / p, rq = rho / q, h2pq = .5 * s;
                        const double ws = -q * s, wq = p * s;
                        const double PAx = pax[b], PAy = pay[b], PAz = paz[b];
                        const double Px = B->px[b], Py = B->py[b], Pz = B->pz[b];
                        const double gb = B->kp[b] * sqrt(s);
                        (void)h2p; (void)rp; (void)rq; (void)h2pq; (void)ws; (void)wq;
                        (void)PAx; (void)PAy; (void)PAz;
#pragma omp simd
                        for (l = 0; l < GL_NL; l++) {
                                const double dx = Px - QX[l], dy = Py - QY[l], dz = Pz - QZ[l];
                                const double T = rho * (dx * dx + dy * dy + dz * dz);
                                const int inr = T < GT_TMAX;
                                const int k = inr ? (int)(T * (1. / GT_STEP) + .5) : 0;
                                const int o = k * GT_TN;
                                const double dt = inr ? k * GT_STEP - T : 0;
                                const double Ta = inr ? GT_TMAX : T, h = .5 / Ta;
                                const double a0 = .886226925452758014 / sqrt(Ta);
                                const double a1 = a0 * (1 * h);
                                const double a2 = a1 * (3 * h);
                                const double f2 = tab[o + 2] + dt * (1. / 1) * (tab[o + 3] + dt * (1. / 2) * (tab[o + 4] + dt * (1. / 3) * (tab[o + 5] + dt * (1. / 4) * (tab[o + 6] + dt * (1. / 5) * (tab[o + 7] + dt * (1. / 6) * (tab[o + 8]))))));
                                const double ex = tab[GT_N * GT_TN + k] * (1 + dt * (1 + dt * (1. / 2) * (1 + dt * (1. / 3) * (1 + dt * (1. / 4) * (1 + dt * (1. / 5) * (1 + dt * (1. / 6)))))));
                                const double T2 = 2 * T;
                                const double f1 = (T2 * f2 + ex) * (1. / 3);
                                const double f0 = (T2 * f1 + ex) * (1. / 1);
                                const double F0 = inr ? f0 : a0;
                                const double F1 = inr ? f1 : a1;
                                const double F2 = inr ? f2 : a2;
                                const double WPx = ws * dx, WPy = ws * dy, WPz = ws * dz;
                                const double WQx = wq * dx, WQy = wq * dy, WQz = wq * dz;
                                const double QCx = QCX[l], QCy = QCY[l], QCz = QCZ[l];
                                (void)WPx; (void)WPy; (void)WPz; (void)WQx; (void)WQy; (void)WQz;
                                (void)QCx; (void)QCy; (void)QCz;
                                const double g = gb * KP[l];
                                const double x000_000_0 = F0;
                                const double x000_000_1 = F1;
                                const double x100_000_0 = PAx * x000_000_0 + WPx * x000_000_1;
                                const double x010_000_0 = PAy * x000_000_0 + WPy * x000_000_1;
                                const double x001_000_0 = PAz * x000_000_0 + WPz * x000_000_1;
                                const double x000_000_2 = F2;
                                const double x100_000_1 = PAx * x000_000_1 + WPx * x000_000_2;
                                const double x200_000_0 = PAx * x100_000_0 + WPx * x100_000_1 + 1 * h2p * (x000_000_0 - rp * x000_000_1);
                                const double x010_000_1 = PAy * x000_000_1 + WPy * x000_000_2;
                                const double x110_000_0 = PAx * x010_000_0 + WPx * x010_000_1;
                                const double x001_000_1 = PAz * x000_000_1 + WPz * x000_000_2;
                                const double x101_000_0 = PAx * x001_000_0 + WPx * x001_000_1;
                                const double x020_000_0 = PAy * x010_000_0 + WPy * x010_000_1 + 1 * h2p * (x000_000_0 - rp * x000_000_1);
                                const double x011_000_0 = PAy * x001_000_0 + WPy * x001_000_1;
                                const double x002_000_0 = PAz * x001_000_0 + WPz * x001_000_1 + 1 * h2p * (x000_000_0 - rp * x000_000_1);
                                v[0 * GL_NL + l] = g * x100_000_0;
                                v[1 * GL_NL + l] = g * x010_000_0;
                                v[2 * GL_NL + l] = g * x001_000_0;
                                v[3 * GL_NL + l] = g * x200_000_0;
                                v[4 * GL_NL + l] = g * x110_000_0;
                                v[5 * GL_NL + l] = g * x101_000_0;
                                v[6 * GL_NL + l] = g * x020_000_0;
                                v[7 * GL_NL + l] = g * x011_000_0;
                                v[8 * GL_NL + l] = g * x002_000_0;
                        }
                        for (cb = 0; cb < ncb; cb++) {
                                const double cbv = B->c[(size_t)cb * B->ld + b];
                                for (kc = 0; kc < nck; kc++) {
                                        const double wc = cbv * K->c[kc * GL_MAXP + t];
                                        double *so = SK + (size_t)(kc * ncb + cb) * 9 * GL_NL;
#pragma omp simd
                                        for (i = 0; i < 9 * GL_NL; i++) so[i] += wc * v[i];
                                }
                        }
                }
        }
        if (!any) return 0;
        double AB[3];
        for (i = 0; i < 3; i++) AB[i] = bs ? -B->rij[i] : B->rij[i];
        (void)AB;
        const double *CDx = K->cd[0], *CDy = K->cd[1], *CDz = K->cd[2];
        const double *CD[3] = {CDx, CDy, CDz};
        (void)CD;
        int ci, cj, ck, cl;
        for (cl = 0; cl < K->ncj; cl++)
        for (ck = 0; ck < K->nci; ck++)
        for (cj = 0; cj < B->ncj; cj++)
        for (ci = 0; ci < B->nci; ci++) {
                const int cpos[4] = {ci, cj, ck, cl};
                const double *sk = SK + ((size_t)(cl * K->nci + ck) * ncb + cj * B->nci + ci) * 9 * GL_NL;
                double *o = out + (cpos[pos[0]] * 3 * st[0] + cpos[pos[1]] * 3 * st[1]
                          + cpos[pos[2]] * 1 * st[2] + cpos[pos[3]] * 1 * st[3]) * GL_NL;
                double HB[9 * GL_NL];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 0 * GL_NL)[i] = (sk + 3 * GL_NL)[i] + AB[0] * (sk + 0 * GL_NL)[i];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 1 * GL_NL)[i] = (sk + 4 * GL_NL)[i] + AB[1] * (sk + 0 * GL_NL)[i];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 2 * GL_NL)[i] = (sk + 5 * GL_NL)[i] + AB[2] * (sk + 0 * GL_NL)[i];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 3 * GL_NL)[i] = (sk + 4 * GL_NL)[i] + AB[0] * (sk + 1 * GL_NL)[i];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 4 * GL_NL)[i] = (sk + 6 * GL_NL)[i] + AB[1] * (sk + 1 * GL_NL)[i];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 5 * GL_NL)[i] = (sk + 7 * GL_NL)[i] + AB[2] * (sk + 1 * GL_NL)[i];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 6 * GL_NL)[i] = (sk + 5 * GL_NL)[i] + AB[0] * (sk + 2 * GL_NL)[i];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 7 * GL_NL)[i] = (sk + 7 * GL_NL)[i] + AB[1] * (sk + 2 * GL_NL)[i];
#pragma omp simd
                for (i = 0; i < 1 * GL_NL; i++) (HB + 8 * GL_NL)[i] = (sk + 8 * GL_NL)[i] + AB[2] * (sk + 2 * GL_NL)[i];
                double R[9 * GL_NL];
                for (i = 0; i < 9; i++) {
#pragma omp simd
                        for (l = 0; l < GL_NL; l++) {
                                R[(0 + i) * GL_NL + l] = HB[(i * 1 + 0) * GL_NL + l];
                        }
                }
                {
                const size_t s0 = st[0] * GL_NL, s1 = st[1] * GL_NL, s2 = st[2] * GL_NL, s3 = st[3] * GL_NL;
#pragma omp simd
                for (l = 0; l < GL_NL; l++) {
                        o[0 * s0 + 0 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[0 * GL_NL + l]);
                        o[0 * s0 + 1 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[1 * GL_NL + l]);
                        o[0 * s0 + 2 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[2 * GL_NL + l]);
                        o[1 * s0 + 0 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[3 * GL_NL + l]);
                        o[1 * s0 + 1 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[4 * GL_NL + l]);
                        o[1 * s0 + 2 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[5 * GL_NL + l]);
                        o[2 * s0 + 0 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[6 * GL_NL + l]);
                        o[2 * s0 + 1 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[7 * GL_NL + l]);
                        o[2 * s0 + 2 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1 * R[8 * GL_NL + l]);
                }
                }
        }
        return 1;
}

