                                const double x110_010_0 = QCy * x110_000_0 + WQy * x110_000_1 + 1 * h2pq * x100_000_1;
                                const double x110_001_0 = QCz * x110_000_0 + WQz * x110_000_1;
                                const double x001_000_0 = PAz * x000_000_0 + WPz * x000_000_1;
