                                v[2 * GL_NL + l] = g * x200_001_0;
                                v[3 * GL_NL + l] = g * x110_100_0;
                                v[4 * GL_NL + l] = g * x110_010_0;
                                v[5 * GL_NL + l] = g * x110_001_0;
                                v[6 * GL_NL + l] = g * x101_100_0;
                                v[7 * GL_NL + l] = g * x101_010_0;
                                v[8 * GL_NL + l] = g * x101_001_0;
                                v[9 * GL_NL + l] = g * x020_100_0;
                                v[10 * GL_NL + l] = g * x020_010_0;
                                v[11 * GL_NL + l] = g * x020_001_0;
