                                const double ex = tab[GT_N * GT_TN + k] * (1 + dt * (1 + dt * (1. / 2) * (1 + dt * (1. / 3) * (1 + dt * (1. / 4) * (1 + dt * (1. / 5) * (1 + dt * (1. / 6)))))));
                                const double T2 = 2 * T;
                                const double f5 = (T2 * f6 + ex) * (1. / 11);
                                const double f4 = (T2 * f5 + ex) * (1. / 9);
                                const double f3 = (T2 * f4 + ex) * (1. / 7);
