                        o[3 * s0 + 0 * s1 + 4 * s2 + 4 * s3 + l] = fac * (0.326033406180041174 * R[2 * GL_NL + l] + -0.326033406180041174 * R[20 * GL_NL + l] + -0.326033406180041174 * R[110 * GL_NL + l] + 0.326033406180041174 * R[128 * GL_NL + l]);
