                        o[3 * s0 + 2 * s1 + 0 * s2 + 0 * s3 + l] = fac * (1.09254843059207918 * R[8 * GL_NL + l]);
                        o[4 * s0 + 0 * s1 + 0 * s2 + 0 * s3 + l] = fac * (0.546274215296039589 * R[0 * GL_NL + l] + -0.546274215296039589 * R[9 * GL_NL + l]);
                        o[4 * s0 + 1 * s1 + 0 * s2 + 0 * s3 + l] = fac * (0.546274215296039589 * R[1 * GL_NL + l] + -0.546274215296039589 * R[10 * GL_NL + l]);
                        o[4 * s0 + 2 * s1 + 0 * s2 + 0 * s3 + l] = fac * (0.546274215296039589 * R[2 * GL_NL + l] + -0.546274215296039589 * R[11 * GL_NL + l]);
